beta_pairs_text <- function(pairs)if(length(pairs))paste(vapply(pairs,paste,character(1),collapse="\t"),collapse="\n") else ""
beta_pairs_parse <- function(text) {
 if(!nzchar(trimws(text)))return(list())
 out<-strsplit(strsplit(text,"\n",fixed=TRUE)[[1]],"\t",fixed=TRUE)
 if(any(lengths(out)!=2L))stop("Pairs: two exact group labels separated by TAB per line.")
 out
}
beta_budget_ui <- function(prefix,s) shiny::tagList(shiny::fluidRow(shiny::column(4,shiny::numericInput(paste0(prefix,"budget"),"Requested permutation budget",s$budget,min=1,max=99999,step=1)),shiny::column(4,shiny::numericInput(paste0(prefix,"seed"),"Explicit random seed",s$seed,min=0,max=.Machine$integer.max,step=1)),shiny::column(4,shiny::selectInput(paste0(prefix,"mode"),"Enumeration mode",c("Automatic: enumerate small spaces"="automatic","Sample distinct legal exchanges"="sampled","Exhaustive (bounded space only)"="exhaustive"),s$mode,selectize=FALSE))),shiny::helpText("Initial sampled budget 9,999 is editable, not a guarantee of adequacy. Small spaces contain fewer legal exchanges. Exhaustive is capped at 10,000 including identity; stored matrices at five million indices. Larger budgets cost more time and memory. Actual counts and p-value grid are reported after generation."))
beta_server <- function(input,output,session,state,status) {
 safe<-function(expr)tryCatch(force(expr),error=function(e)status(conditionMessage(e)))
 fallback<-function(id,value){v<-input[[id]];if(is.null(v))value else v}
 draft<-shiny::reactiveVal(NULL)
 calc<-shiny::reactive({
  old<-if(is.null(state()$beta))beta_settings() else state()$beta$settings
  metric<-fallback("beta_metric",old$metric);s<-beta_settings(list(metric=metric))
  for(n in intersect(names(s),names(old)))if(identical(metric,old$metric))s[[n]]<-old[[n]]
  for(n in setdiff(names(s),c("metric","source","units")))s[[n]]<-fallback(paste0("beta_",n),s[[n]])
  if(metric!="bray")s$correction<-"none"
  s
 })
 styles<-shiny::reactive({s<-beta_plot_settings(state()$beta$plot_settings)
  for(n in c("group","facet","colour","colour_type","fixed_colour","palette","shape","fixed_shape","trajectories","axis_x","axis_y","positive_share","group_centres"))s[[n]]<-fallback(paste0("beta_",n),s[[n]])
  s$colours<-alpha_manual_parse(fallback("beta_colours",alpha_manual_text(s$colours)));s$shapes<-alpha_manual_parse(fallback("beta_shapes",alpha_manual_text(s$shapes)),TRUE)
  for(n in c("format","width","height","units","dpi"))s$figure[[n]]<-fallback(paste0("beta_fig_",n),s$figure[[n]]);s
 })
 comparison<-shiny::reactive({s<-beta_comparison_settings(if(is.null(state()$beta$comparison))list() else state()$beta$comparison$settings)
  for(n in setdiff(names(s),c("pairs","permutations")))s[[n]]<-fallback(paste0("beta_cmp_",n),s[[n]])
  for(n in c("factors","covariates","nuisance"))s[[n]]<-as.character(s[[n]])
  for(n in names(s$permutations))s$permutations[[n]]<-fallback(paste0("beta_perm_",n),s$permutations[[n]])
  s$pairs<-beta_pairs_parse(fallback("beta_cmp_pairs",beta_pairs_text(s$pairs)));s
 })
 dispersion<-shiny::reactive({old<-state()$beta$dispersion$settings;if(is.null(old))old<-list();bias<-old$bias_adjust;old$bias_adjust<-NULL;s<-beta_comparison_settings(old)
  for(n in c("route","group","unit","verified","evidence","missing","geometry"))s[[n]]<-fallback(paste0("beta_disp_",n),s[[n]])
  s$assignment<-"independent_units";for(n in names(s$permutations))s$permutations[[n]]<-fallback(paste0("beta_dperm_",n),s$permutations[[n]])
  s$bias_adjust<-fallback("beta_disp_bias_adjust",if(is.null(bias))FALSE else bias);s
 })
 pending<-shiny::reactive({b<-state()$beta;if(diversity_rank_pending(input,state(),"beta"))return(TRUE);if(is.null(b))return(FALSE)
  tryCatch(!isTRUE(all.equal(beta_settings(calc()),b$settings))||!isTRUE(all.equal(beta_plot_settings(styles()),b$plot_settings))||(!is.null(b$comparison)&&!isTRUE(all.equal(beta_comparison_settings(comparison()),b$comparison$settings)))||(!is.null(b$dispersion)&&!isTRUE(all.equal(dispersion(),b$dispersion$settings))),error=function(e)TRUE)
 })
 guard<-function(){if(pending())stop("Beta controls have unapplied edits. Apply calculation, styles or the relevant inference before saving/exporting.");if(!is.null(state()$beta))beta_current(state())}
 output$beta_calculation_controls<-shiny::renderUI({
  s<-if(is.null(state()$beta))beta_settings() else state()$beta$settings
  shiny::tagList(shiny::selectInput("beta_metric","Distance method",c("Bray"="bray","Aitchison (ordinary CLR)"="aitchison","Robust Aitchison (rCLR/completion)"="robust.aitchison"),s$metric,selectize=FALSE),
   shiny::uiOutput("beta_metric_controls"),shiny::conditionalPanel("input.beta_metric == 'bray'",shiny::selectInput("beta_correction","PCoA geometry",c("Original geometry (Bray retains negative eigenvalues)"="none","Separate Lingoes-corrected ordination"="lingoes"),s$correction,selectize=FALSE)),
   shiny::textOutput("beta_cohort_budget"),
   shiny::tags$details(shiny::tags$summary("Advanced computational safety"),
    shiny::numericInput("beta_max_samples","Maximum samples per calculation",s$max_samples,min=2,max=2000),
    shiny::helpText("This limit stops oversized calculations; it never selects or drops samples. Pairwise distances grow as n(n-1)/2, and PCoA needs additional matrix workspace. The default 500 and allowed range 2 to 2000 are engineering limits, not measured hardware capacity or biological thresholds. Review this budget deliberately, or select a smaller cohort in Preparation. It does not filter taxa or rarefy reads.")))
 })
 output$beta_metric_controls<-shiny::renderUI({
  old<-state()$beta$settings;metric<-fallback("beta_metric",if(is.null(old))"bray" else old$metric)
  s<-if(!is.null(old)&&identical(metric,old$metric))old else beta_settings(list(metric=metric))
  if(metric=="bray")return(shiny::helpText("Bray uses retained named measurements without reclosure."))
  if(metric=="aitchison")return(shiny::tagList(
   shiny::selectInput("beta_zero_policy","Ordinary CLR zero policy",c("Positive values only; no addition"="positive","Explicit addition to every cell"="add"),s$zero_policy,selectize=FALSE),
   shiny::numericInput("beta_pseudocount","Addition in proportion units (0 for positive-only)",s$pseudocount,min=0,step=.0001),
   shiny::helpText("Natural-log CLR followed by Euclidean distance. Zeros block positive-only calculation. Explicit addition changes every retained value before log; no universal value is recommended. No-add distances are sample-scale invariant; fixed addition can change results with scale. Original Euclidean geometry is used; the Bray correction control does not apply.")))
  shiny::tagList(shiny::numericInput("beta_robust_rank","Completion rank",s$robust_rank,min=1,max=1000,step=1),
   shiny::numericInput("beta_robust_niter","Maximum completion iterations",s$robust_niter,min=2,max=1000,step=1),
   shiny::numericInput("beta_robust_tol","Completion tolerance",s$robust_tol,min=0,step=.00001),
   shiny::helpText("No pseudocount. rCLR treats zeros as missing; vegan optspace completes and centres the whole matrix. Positive data need no completion. Rank must fit the sample/feature dimensions. Saved diagnostics report iterations, residual history and unmet tolerance. Sparse or structural-zero data are not automatically suitable. Original Euclidean geometry is used; the Bray correction control does not apply."))
 })
 output$beta_cohort_budget<-shiny::renderText({
  p<-state();if(is.null(p$experiment))return("No active cohort. Resolve Data setup or Preparation first.")
  n<-ncol(p$experiment);limit<-calc()$max_samples
  if(n<2L)return(paste("Applied cohort:",n,"sample. Beta needs at least two; review the cohort in Preparation."))
  if(length(limit)!=1L||!is.finite(limit)||limit<2||limit>2000||limit!=floor(limit))return(paste("Applied cohort:",n,"samples. Enter a whole-number advanced computational limit from 2 to 2000."))
  if(n>limit)paste("Applied cohort:",n,"samples; selected safety limit:",limit,". Calculation will stop without dropping samples. Review Advanced computational safety or select a cohort in Preparation.") else paste("Applied cohort:",n,"samples. All will be used.")
 })
 output$beta_style_controls<-shiny::renderUI({p<-state();shiny::req(p$experiment);s<-beta_plot_settings(p$beta$plot_settings);md<-as.data.frame(SummarizedExperiment::colData(p$experiment));fields<-names(md);catfields<-fields[!vapply(md,is.numeric,logical(1))]
  shiny::tagList(shiny::fluidRow(shiny::column(6,select_field("beta_group","Descriptive grouping (independent of point styles)",fields,s$group)),shiny::column(6,select_field("beta_facet","Facet",fields,s$facet))),shiny::checkboxInput("beta_group_centres","Label descriptive projected group centres",s$group_centres),shiny::fluidRow(shiny::column(6,select_field("beta_colour","Colour metadata",fields,s$colour)),shiny::column(6,shiny::selectInput("beta_colour_type","Colour scale",c("categorical","continuous"),s$colour_type,selectize=FALSE))),shiny::fluidRow(shiny::column(6,shiny::textInput("beta_fixed_colour","Fixed colour (when no mapping)",s$fixed_colour)),shiny::column(6,shiny::selectInput("beta_palette","Named palette",grDevices::hcl.pals(),s$palette,selectize=FALSE))),shiny::fluidRow(shiny::column(6,select_field("beta_shape","Categorical shape metadata",catfields,s$shape)),shiny::column(6,shiny::numericInput("beta_fixed_shape","Fixed shape (0-25)",s$fixed_shape,min=0,max=25))),shiny::textAreaInput("beta_colours","Custom colours: exact level, TAB, colour per line",alpha_manual_text(s$colours)),shiny::textAreaInput("beta_shapes","Custom shapes: exact level, TAB, integer per line",alpha_manual_text(s$shapes)),shiny::helpText("Colour and shape are independent of group/facet. Shapes are categorical; at most 26 distinct symbols. Shapes 21-25 use selected colour as both fill and outline. Missing levels are labelled; continuous missing colour is grey. No refit occurs."),shiny::fluidRow(shiny::column(6,shiny::numericInput("beta_axis_x","Horizontal positive axis",s$axis_x,min=1)),shiny::column(6,shiny::numericInput("beta_axis_y","Vertical positive axis",s$axis_y,min=1))),shiny::checkboxInput("beta_positive_share","Label shares of positive eigenvalue sum",s$positive_share),shiny::checkboxInput("beta_trajectories","Connect verified unit trajectories in declared visit/condition order",s$trajectories),shiny::fluidRow(shiny::column(3,shiny::selectInput("beta_fig_format","Figure format",c("png","pdf",if(requireNamespace("svglite",quietly=TRUE))"svg"),s$figure$format,selectize=FALSE)),shiny::column(3,shiny::numericInput("beta_fig_width","Width",s$figure$width,min=.5,max=40)),shiny::column(3,shiny::numericInput("beta_fig_height","Height",s$figure$height,min=.5,max=40)),shiny::column(3,shiny::numericInput("beta_fig_dpi","DPI",s$figure$dpi,min=72,max=600))),shiny::selectInput("beta_fig_units","Figure units",c("in","cm","mm"),s$figure$units,selectize=FALSE))
 })
 output$beta_comparison_controls<-shiny::renderUI({p<-state();shiny::req(p$experiment);fields<-names(as.data.frame(SummarizedExperiment::colData(p$experiment)));s<-beta_comparison_settings(if(is.null(p$beta$comparison))list() else p$beta$comparison$settings)
  shiny::tagList(shiny::selectInput("beta_cmp_route","Intended hypothesis and exchange scheme",c("Independent units: unrestricted profile exchange"="independent","Independent conditional effect: reduced-model permutation"="conditional","Verified pairs: exchange conditions within each pair"="paired","Verified repeated exchangeable conditions within units"="within","Randomized complete trajectories: exchange whole units"="trajectory"),s$route,selectize=FALSE),shiny::selectInput("beta_cmp_test","Test definition (independent models)",c("Overall joint model"="overall","Sequential: entered term order matters"="sequential","Marginal: each eligible term after the others"="marginal"),s$test,selectize=FALSE),select_field("beta_cmp_group","Tested group / within-unit condition",fields,s$group),shiny::selectInput("beta_cmp_factors","Additional tested factors (independent models)",fields,s$factors,multiple=TRUE,selectize=FALSE),shiny::selectInput("beta_cmp_covariates","Numeric covariates (tested in independent; nuisance in conditional)",fields,s$covariates,multiple=TRUE,selectize=FALSE),shiny::selectInput("beta_cmp_nuisance","Explicit nuisance / conditioning terms (conditional route)",fields,s$nuisance,multiple=TRUE,selectize=FALSE),shiny::textInput("beta_cmp_reference","Optional exact reference group",s$reference),select_field("beta_cmp_unit","Independent unit / pair / subject ID",fields,s$unit),select_field("beta_cmp_visit","Matched visit ID (whole trajectories only)",fields,s$visit),shiny::selectInput("beta_cmp_assignment","Declared sampling / assignment units",c("Unknown (inference blocked)"="unknown","Independent units, one row each"="independent_units","Independent subjects with repeated observations"="independent_subjects"),s$assignment,selectize=FALSE),shiny::checkboxInput("beta_cmp_verified","I verified unit identity and assignment using study evidence",s$verified),shiny::textAreaInput("beta_cmp_evidence","Evidence and null-exchangeability justification",s$evidence),shiny::checkboxInput("beta_cmp_exchangeable","Within conditions are exchangeable, or whole-unit group assignment was randomized (as selected above)",s$exchangeable),shiny::checkboxInput("beta_cmp_ordered_time","Within-unit variable is ordered/serial time (within shuffling blocked)",s$ordered_time),shiny::helpText("Pairs/repeated conditions keep members in their own unit. Serial time is not automatically exchangeable. Whole trajectories keep matched visits together and use a unit-level equal-weight distance; they do not test a general treatment-by-time interaction. Nested/crossed, cyclic/series and bespoke how() code are unsupported. Conditional vegan 2.7-5 permutes reduced response and nuisance rows, then re-residualizes fixed constraints; it is not simply shuffling group labels."),shiny::fluidRow(shiny::column(6,shiny::selectInput("beta_cmp_missing","Missing/incomplete metadata policy",c("Fail with explanation"="fail","Explicit complete-case / whole-unit exclusion"="complete"),s$missing,selectize=FALSE)),shiny::column(6,shiny::selectInput("beta_cmp_geometry","Test distance",c("Saved selected distance"="original","Explicit selected ordination geometry"="ordination"),s$geometry,selectize=FALSE))),beta_budget_ui("beta_perm_",s$permutations),shiny::textAreaInput("beta_cmp_pairs","Prespecified pairs: exact level 1, TAB, level 2 per line",beta_pairs_text(s$pairs)),shiny::textInput("beta_cmp_family","Planned pair-family name",s$family),shiny::selectInput("beta_cmp_adjust","Family adjustment",c("Holm"="holm","BH (exploratory FDR)"="BH"),s$adjust,selectize=FALSE),shiny::helpText("Every pair rebuilds its cohort, rank and legal exchanges. Failures remain in the planned family. Other predictors are nuisance terms for a pairwise group test; omnibus/sequential/marginal results have a separate named family."))
 })
 output$beta_dispersion_controls<-shiny::renderUI({p<-state();shiny::req(p$experiment);fields<-names(as.data.frame(SummarizedExperiment::colData(p$experiment)));old<-p$beta$dispersion$settings;bias<-old$bias_adjust;old$bias_adjust<-NULL;s<-beta_comparison_settings(if(is.null(old))list() else old)
  shiny::tagList(shiny::selectInput("beta_disp_route","Dispersion design",c("Independent one-factor observations"="independent","Repeated / clustered (unsupported)"="paired"),s$route,selectize=FALSE),select_field("beta_disp_group","Dispersion grouping",fields,s$group),select_field("beta_disp_unit","Independent unit ID",fields,s$unit),shiny::checkboxInput("beta_disp_verified","I verified one observation per independent unit",s$verified),shiny::textAreaInput("beta_disp_evidence","Dispersion design evidence",s$evidence),shiny::checkboxInput("beta_disp_bias_adjust","Apply labelled small-sample bias multiplier",isTRUE(bias)),shiny::selectInput("beta_disp_missing","Missingness policy",c("fail","complete"),s$missing,selectize=FALSE),shiny::selectInput("beta_disp_geometry","Dispersion distance",c("Saved selected distance"="original","Selected ordination geometry"="ordination"),s$geometry,selectize=FALSE),beta_budget_ui("beta_dperm_",s$permutations),shiny::helpText("Separate plan: permutes residuals of the one-factor spatial-median-distance model. It does not inherit community-test restrictions. Observed F is compared to residual-permutation F; exhaustive residual permutations are not an exact raw-label test."))
 })
 shiny::observeEvent(input$beta_apply,safe({p<-state();shiny::req(p);if(diversity_rank_pending(input,p,"beta"))stop("Apply the pending shared rank before calculating beta.");state(apply_beta(p,calc(),if(is.null(p$beta))list() else p$beta$plot_settings));draft(NULL);status("Distance/PCoA applied. Inspect geometry; previous inference must be explicitly reapplied.")}))
 shiny::observeEvent(input$beta_style_apply,safe({p<-state();shiny::req(p$beta);p$beta$plot_settings<-beta_plot_settings(styles());plot_beta(p);state(p);status("Beta styles applied; distances and inference unchanged.")}))
 shiny::observeEvent(input$beta_preview,safe({p<-state();beta_current(p,inference=FALSE);s<-beta_comparison_settings(comparison());z<-beta_inference_data(p$beta,s);algorithm<-if(s$route%in%c("conditional","paired","within"))"Draft reduced partial response and nuisance exchange" else if(s$route=="trajectory")"Draft whole trajectory exchange" else "Draft raw profile exchange";draft(list(plan=beta_permutation_plan(z$frame,s$permutations,z$blocks,algorithm,z$mapping),settings=s));status("Draft legal exchanges generated without fitting. Model rank and inferential result are checked when applied.")}))
 shiny::observeEvent(input$beta_compare,safe({p<-state();beta_current(p,inference=FALSE);if(!isTRUE(all.equal(beta_settings(calc()),p$beta$settings)))stop("Apply pending calculation settings first.");p$beta$comparison<-compare_beta(p$beta,comparison());state(p);draft(NULL);status(paste("Beta comparison",p$beta$comparison$status,p$beta$comparison$reason))}))
 shiny::observeEvent(input$beta_disp_apply,safe({p<-state();beta_current(p,inference=FALSE);if(!isTRUE(all.equal(beta_settings(calc()),p$beta$settings)))stop("Apply pending calculation settings first.");p$beta$dispersion<-beta_dispersion(p$beta,dispersion());state(p);status(paste("Beta dispersion",p$beta$dispersion$status,p$beta$dispersion$reason))}))
 output$beta_status<-shiny::renderText({b<-state()$beta;if(is.null(b))return("Choose a distance and calculate to begin.");paste(beta_metric_label(b$settings$metric),b$status,b$reason,paste(b$transformation$warnings,collapse="; "),if(!is.null(b$transformation$optimizer))paste("Completion:",b$transformation$optimizer$status))})
 output$beta_pending<-shiny::renderText(diversity_result_message(state(),"beta",pending()))
 output$beta_plot_panel<-shiny::renderUI(diversity_plot_panel(state(),"beta"))
 output$beta_plot<-shiny::renderPlot({shiny::req(diversity_plot_available(state(),"beta"),state()$beta$ordination$status=="ready");plot_beta(state())})
 output$beta_spectrum<-shiny::renderPlot({shiny::req(diversity_plot_available(state(),"beta"),state()$beta$ordination$status=="ready");plot_beta_eigenvalues(state())})
 output$beta_scores<-shiny::renderTable(state()$beta$ordination$scores,digits=7)
 output$beta_eigenvalues<-shiny::renderTable(state()$beta$ordination$diagnostics,digits=8)
 format_p<-function(d){if(!is.null(d))for(n in intersect(c("p_raw","p_adjusted"),names(d)))d[[n]]<-ifelse(is.na(d[[n]]),NA_character_,format(d[[n]],digits=8,scientific=TRUE));d}
 output$beta_tests<-shiny::renderTable(format_p(state()$beta$comparison$tests),digits=7)
 output$beta_pairs<-shiny::renderTable(format_p(state()$beta$comparison$pairwise),digits=7)
 output$beta_comparison_status<-shiny::renderText({r<-state()$beta$comparison;paste(r$status,r$reason)})
 output$beta_dispersion_status<-shiny::renderText({r<-state()$beta$dispersion;paste(r$status,r$reason)})
 output$beta_dispersion_tests<-shiny::renderTable(format_p(state()$beta$dispersion$tests),digits=7)
 output$beta_dispersion_plot<-shiny::renderPlot({shiny::req(diversity_plot_available(state(),"beta"),state()$beta$dispersion$status=="ready");plot_beta_dispersion(state())})
 output$beta_plan_selector<-shiny::renderUI({r<-state()$beta$comparison$results;choices<-c(if(!is.null(draft()))c("Draft preview (not a fitted result)"="draft"),if(length(r))setNames(names(r),paste("Applied",names(r))),if(!is.null(state()$beta$dispersion))c("Applied dispersion"="dispersion"));if(!length(choices))return(shiny::p("Preview or apply a hypothesis to inspect its legal exchanges."));shiny::selectInput("beta_plan_selected","Saved plan to inspect",choices,selected=if(!is.null(draft()))"draft" else names(r)[1],selectize=FALSE)})
 selected<-shiny::reactive({id<-fallback("beta_plan_selected",if(!is.null(draft()))"draft" else "omnibus");if(id=="draft")return(list(permutation=draft()$plan,status="draft",reason="No fit; model rank is checked on apply."));if(id=="dispersion")state()$beta$dispersion else state()$beta$comparison$results[[id]]})
 output$beta_plan_summary<-shiny::renderText({r<-selected();paste(r$status,r$reason,r$formula,r$permutation$summary,sep="\n")})
 output$beta_plan_preview<-shiny::renderTable(selected()$permutation$preview)
 output$beta_plan_invariants<-shiny::renderTable(selected()$permutation$invariants)
 output$beta_transform_diagnostics<-shiny::renderPrint({tr<-state()$beta$transformation;if(is.null(tr))cat("No log-ratio transformation saved.") else print(tr[c("status","reason","formula","addition_scope","affected_cells","source_zeros","warnings","optimizer")])})
 output$beta_calls<-shiny::renderText({r<-selected();paste(c(state()$beta$transformation$readable_call,r$permutation$readable_call,r$readable_call),collapse="\n")})
 output$beta_permutation_plot<-shiny::renderPlot({id<-fallback("beta_plan_selected","omnibus");shiny::req(diversity_plot_available(state(),"beta"),id!="draft",selected()$status=="ready");plot_beta_permutations(state(),result=id,dispersion=id=="dispersion")})
 output$beta_figure<-shiny::downloadHandler(filename=function()paste0("beta.",beta_plot_settings(state()$beta$plot_settings)$figure$format),content=function(file){guard();alpha_write_figure(plot_beta(state()),file,beta_plot_settings(state()$beta$plot_settings)$figure)})
 output$beta_data<-shiny::downloadHandler(filename=function()"beta-plotted-coordinates.tsv",content=function(file){guard();utils::write.table(attr(plot_beta(state()),"beta_data"),file,sep="\t",row.names=FALSE,quote=TRUE)})
 shiny::observeEvent(input$beta_export,safe({guard();export_beta(state(),input$beta_export_path);status(paste("Beta export complete:",input$beta_export_path))}))
 guard
